def served(path):
    """Contenu et type d'un élément d'installation, ou None si le chemin n'en est pas un."""
    if path == '/manifest.webmanifest':
        return json.dumps(MANIFEST, ensure_ascii=False).encode(), 'application/manifest+json'
    if path in ICONS:
        return base64.b64decode(ICONS[path]), 'image/png'
    return None
